          connected == other.connected &&
          reconnecting == other.reconnecting &&
          health == other.health &&
          hopRttMs == other.hopRttMs &&
          persistent == other.persistent &&
          program == other.program &&
          closed == other.closed &&
          unknownSystems == other.unknownSystems &&
          moshFallback == other.moshFallback;
}

enum SessionEventKind {
  /// The hops of the connection (`route`), before the first stage.
  route,
  stage,
  prompt,
  connected,

  /// The connection was lost and is tried again (`reconnecting`).
  reconnecting,

  /// How a live connection is doing (`health`).
  health,

  /// The round trip to each jump host (`hop_rtt_ms`).
  hops,

  /// Saved hosts changed (connecting told their system): read them
  /// again. `unknown_systems`: the ones just found not to tell their
  /// system, to offer reading `/etc/os-release`.
  hostsChanged,

  /// How the shell of a host with a persistent session started
  /// (`persistent`).
  persistent,

  /// Mosh was asked for and the session goes over SSH (`mosh_fallback`).
  moshFallback,

  /// A local program is running (`program`).
  started,
  closed,
}

enum StageKind { connecting, authenticating, openingShell, openingSftp }

class StageView {
  /// From 0; `hops` in total, the target last.
  final int hop;
  final int hops;
  final String label;
  final StageKind stage;

  const StageView({
    required this.hop,
    required this.hops,
    required this.label,
    required this.stage,
  });

  @override
  int get hashCode =>
      hop.hashCode ^ hops.hashCode ^ label.hashCode ^ stage.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is StageView &&
          runtimeType == other.runtimeType &&
          hop == other.hop &&
          hops == other.hops &&
          label == other.label &&
          stage == other.stage;
}

/// Damage since the last poll, and how input should be routed.
class TermFrame {
  /// Damage frame v1 (`openward-term`, frame.rs).
  final Uint8List frame;
  final bool mouseTracking;
  final bool bracketedPaste;
  final bool reportAllKeys;
  final bool keypadApplication;

  /// `0xRRGGBB` the program set for itself over the theme (OSC 10, 11,
  /// 12); its palette changes come painted in the frame.
  final int? programForeground;
  final int? programBackground;
  final int? programCursor;
  final bool altScreen;
  final String title;

  /// The selection as it stands now (empty: none), to paint over the
  /// screen.
  final List<SelectedRange> selection;

  /// A BEL arrived since the last frame.
  final bool bell;
  final bool cursorBlinks;

  /// While the find bar is open.
  final SearchView? search;

  const TermFrame({
    required this.frame,
    required this.mouseTracking,
    required this.bracketedPaste,
    required this.reportAllKeys,
    required this.keypadApplication,
    this.programForeground,
    this.programBackground,
    this.programCursor,
    required this.altScreen,
    required this.title,
    required this.selection,
    required this.bell,
    required this.cursorBlinks,
    this.search,
  });

  @override
  int get hashCode =>
      frame.hashCode ^
      mouseTracking.hashCode ^
      bracketedPaste.hashCode ^
      reportAllKeys.hashCode ^
      keypadApplication.hashCode ^
      programForeground.hashCode ^
      programBackground.hashCode ^
      programCursor.hashCode ^
      altScreen.hashCode ^
      title.hashCode ^
      selection.hashCode ^
      bell.hashCode ^
      cursorBlinks.hashCode ^
      search.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is TermFrame &&
          runtimeType == other.runtimeType &&
          frame == other.frame &&
          mouseTracking == other.mouseTracking &&
          bracketedPaste == other.bracketedPaste &&
          reportAllKeys == other.reportAllKeys &&
          keypadApplication == other.keypadApplication &&
          programForeground == other.programForeground &&
          programBackground == other.programBackground &&
          programCursor == other.programCursor &&
          altScreen == other.altScreen &&
          title == other.title &&
          selection == other.selection &&
          bell == other.bell &&
          cursorBlinks == other.cursorBlinks &&
          search == other.search;
}

/// What a hidden tab reads instead of the screen.
class TermMeta {
  final String title;

  /// A BEL arrived since the last look.
  final bool bell;

  const TermMeta({required this.title, required this.bell});

  @override
  int get hashCode => title.hashCode ^ bell.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is TermMeta &&
          runtimeType == other.runtimeType &&
          title == other.title &&
          bell == other.bell;
}

enum TrustKind { known, certified, new_ }

/// The screen from where typing began up to the cursor, and what follows
/// the cursor on its row (a suggestion the shell shows, or the rest of a
/// line being edited).
class TypedLine {
  final String text;
  final String after;

  const TypedLine({required this.text, required this.after});

  @override
  int get hashCode => text.hashCode ^ after.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is TypedLine &&
          runtimeType == other.runtimeType &&
          text == other.text &&
          after == other.after;
}
